<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?>
<section class="py-4 border-bottom bg-light"><div class="container"><h1 class="h3 mb-1">Blog</h1><p class="text-muted mb-0">Buying guides, product notes and store updates.</p></div></section>
<section class="py-5"><div class="container"><div class="row g-3"><?php if (empty($posts)): ?><div class="col-12"><?php echo empty_state('No posts yet', 'Published posts will appear here.', 'fa-newspaper'); ?></div><?php else: foreach ($posts as $post): ?><div class="col-md-6 col-lg-4"><article class="card h-100"><?php if ($post->featured_image): ?><a href="<?php echo site_url('blog/'.$post->slug); ?>"><img class="card-img-top" src="<?php echo upload_url($post->featured_image); ?>" alt="<?php echo html_escape($post->title); ?>" loading="lazy"></a><?php endif; ?><div class="card-body"><h2 class="h5"><a href="<?php echo site_url('blog/'.$post->slug); ?>"><?php echo html_escape($post->title); ?></a></h2><p class="text-muted"><?php echo html_escape($post->excerpt); ?></p><span class="small text-muted"><?php echo format_date($post->published_at ?: $post->created_at); ?></span></div></article></div><?php endforeach; endif; ?></div></div></section>
